#include <iostream>
#include <vector>
#include <string>

int main() {
    std::vector<int> openPositions;
    std::vector<int> closePositions;
    int countSegments;
    std::cin >> countSegments;
    std::string str;
    std::cin >> str;

    for (int i = 0; i < countSegments; i++) {
        if (str[i] == '(') {
            openPositions.push_back(i);
        } else if (str[i] == ')') {
            closePositions.push_back(i);
        }
    }

    int totalWords = 0;
    auto getSegments = [&](const std::string& s, const std::vector<int>& starts, const std::vector<int>& ends) {
        std::vector<std::string> segments;
        for (size_t i = 0; i < starts.size(); i++) {
            segments.push_back(s.substr(starts[i] + 1, ends[i] - starts[i] - 1));
        }
        return segments;
    };

    for (const auto& segment : getSegments(str, openPositions, closePositions)) {
        size_t start = 0;
        size_t pos = 0;
        while ((pos = segment.find('_', start)) != std::string::npos) {
            std::string part = segment.substr(start, pos - start);
            if (!part.empty()) {
                totalWords++;
            }
            start = pos + 1;
        }
        // last part after last underscore
        std::string lastPart = segment.substr(start);
        if (!lastPart.empty()) {
            totalWords++;
        }
    }

    int maxWordLength = 0;
    openPositions.push_back(str.length());
    closePositions.insert(closePositions.begin(), 0);
    size_t startIndex = (str[0] == '(') ? 1 : 0;

    for (size_t i = startIndex; i < closePositions.size(); i++) {
        std::string segment;
        if (str[closePositions[i]] == ')') {
            segment = str.substr(closePositions[i] + 1, openPositions[i] - closePositions[i] - 1);
        } else {
            segment = str.substr(closePositions[i], openPositions[i] - closePositions[i]);
        }
        size_t start = 0;
        size_t pos = 0;
        while ((pos = segment.find('_', start)) != std::string::npos) {
            std::string part = segment.substr(start, pos - start);
            if (part.length() > maxWordLength && part.find('(') == std::string::npos && part.find(')') == std::string::npos) {
                maxWordLength = part.length();
            }
            start = pos + 1;
        }
        // last part after last underscore
        std::string lastPart = segment.substr(start);
        if (lastPart.length() > maxWordLength && lastPart.find('(') == std::string::npos && lastPart.find(')') == std::string::npos) {
            maxWordLength = lastPart.length();
        }
    }

    std::cout << maxWordLength << " " << totalWords << std::endl;

    return 0;
}

